import math
def hyperbolic_distance(z: complex, w: complex) -> float:
    cross_ratio = abs(z - w) / abs(1 - z.conjugate() * w)
    return 2 * math.atanh(min(cross_ratio, 0.9999999))

import cmath
def selberg_zeta(spectrum, s, K=10):
    result = 1+0j
    for l in spectrum:
        for k in range(K):
            result *= (1 - cmath.exp(-(s+k)*l))
    return result

